toolScript:
// Web Audio API logic preserved from existing code
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        let audioCtx;
        let oscillator;
        let gainNode;
        let analyser;
        let isPlaying = false;
        let animationId;
        function initAudio() {
            if (!audioCtx) {
                audioCtx = new AudioContext();
                gainNode = audioCtx.createGain();
                analyser = audioCtx.createAnalyser();
                gainNode.connect(analyser);
                analyser.connect(audioCtx.destination);
                analyser.fftSize = 2048;
                drawVisualizer();
            }
            if (audioCtx.state === 'suspended') {
                audioCtx.resume();
            }
        }
        function toggleAudio() {
            initAudio();
            const btn = document.getElementById('play-btn');
            const icon = document.getElementById('play-icon');
            const text = document.getElementById('play-text');
            const status = document.getElementById('status-text');
            if (isPlaying) {
                stopTone();
                btn.classList.remove('btn-playing');
                icon.innerHTML = '<path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clip-rule="evenodd"></path>';
                text.innerText = "Start Frequency Test";
                status.innerText = "Sensor Offline";
            } else {
                const freq = document.getElementById('freq-slider').value;
                playTone(freq);
                btn.classList.add('btn-playing');
                icon.innerHTML = '<path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clip-rule="evenodd"></path>';
                text.innerText = "Deactivate Signal";
                status.innerText = "Active: " + freq + " Hz";
            }
            isPlaying = !isPlaying;
        }
        function playTone(freq) {
            oscillator = audioCtx.createOscillator();
            oscillator.type = 'sine';
            oscillator.frequency.value = freq;
            gainNode.gain.setValueAtTime(0.001, audioCtx.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.1, audioCtx.currentTime + 0.1);
            oscillator.connect(gainNode);
            oscillator.start();
        }
        function stopTone() {
            if (oscillator) {
                gainNode.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
                oscillator.stop(audioCtx.currentTime + 0.1);
                oscillator = null;
            }
        }
        function updateFrequency(val) {
            document.getElementById('freq-display').innerText = parseInt(val).toLocaleString() + ' Hz';
            calculateAge(val);
            if (isPlaying && oscillator) {
                oscillator.frequency.setValueAtTime(val, audioCtx.currentTime);
                document.getElementById('status-text').innerText = "Active: " + val + " Hz";
            }
        }
        function calculateAge(freq) {
            const ageDisplay = document.getElementById('age-display');
            let age = "Unknown";
            if (freq >= 19000) age = "< 18 Years";
            else if (freq >= 17400) age = "18 - 24 Years";
            else if (freq >= 16000) age = "25 - 30 Years";
            else if (freq >= 15000) age = "30 - 40 Years";
            else if (freq >= 12000) age = "40 - 50 Years";
            else if (freq >= 10000) age = "50 - 60 Years";
            else age = "60+ Years";
            ageDisplay.innerText = age;
        }
        function drawVisualizer() {
            const canvas = document.getElementById("oscilloscope");
            const canvasCtx = canvas.getContext("2d");
            const bufferLength = analyser.frequencyBinCount;
            const dataArray = new Uint8Array(bufferLength);
            canvas.width = canvas.parentElement.offsetWidth;
            canvas.height = canvas.parentElement.offsetHeight;
            function draw() {
                animationId = requestAnimationFrame(draw);
                analyser.getByteTimeDomainData(dataArray);
                canvasCtx.fillStyle = "rgb(15, 23, 42)";
                canvasCtx.fillRect(0, 0, canvas.width, canvas.height);
                canvasCtx.lineWidth = 3;
                canvasCtx.strokeStyle = "rgb(6, 182, 212)";
                canvasCtx.beginPath();
                const sliceWidth = canvas.width * 1.0 / bufferLength;
                let x = 0;
                for (let i = 0; i < bufferLength; i++) {
                    const v = dataArray[i] / 128.0;
                    const y = v * canvas.height / 2;
                    if (i === 0) canvasCtx.moveTo(x, y);
                    else canvasCtx.lineTo(x, y);
                    x += sliceWidth;
                }
                canvasCtx.lineTo(canvas.width, canvas.height / 2);
                canvasCtx.stroke();
            }
            draw();
        }
        calculateAge(10000);
